async function requests(){
 const root=$('#app');
 const layout=(title,desc,content)=>`<main class="in-requests"><div class="in-requests-wrap"><header class="in-requests-header"><span class="in-novel-overline">READER REQUEST DESK</span><h1>${title}</h1><p>${desc}</p></header>${content}</div></main>`;
 let r;
 try{r=await api('/api/requests')}catch(e){root.innerHTML=layout('Request a story','Submit a source link for review.',`<div class="in-requests-state" role="alert">${esc(e.message)} <a href="/login">Sign in</a> and try again.</div>`);return}
 root.innerHTML=layout('Request a story','Suggest a novel for the Imperial catalog. Every request is reviewed before any action is taken.',`
  <section class="in-requests-card"><div class="in-requests-quota"><div><span class="in-novel-overline">WEEKLY REQUEST ALLOWANCE</span><b>${Number(r.used||0)} <small>/ ${Number(r.limit||0)}</small></b><p>Free requests used in the current allowance period.</p></div><div class="in-requests-quota-meter" role="img" aria-label="${Number(r.used||0)} of ${Number(r.limit||0)} free requests used"><span style="width:${r.limit>0?Math.min(100,Math.max(0,Number(r.used||0)/Number(r.limit)*100)):0}%"></span></div></div>
   <form id="req" class="in-requests-form"><label for="requestUrl">Novel source URL</label><input id="requestUrl" name="url" type="url" inputmode="url" autocomplete="url" placeholder="https://example.com/novel/..." required><p>Submit a public source page. Do not submit passwords, private links, or content you do not have permission to share.</p><button class="in-button in-button--primary" type="submit">Submit for review <span aria-hidden="true">↗</span></button></form>
   <div id="reqMsg" class="in-requests-message" role="status" aria-live="polite"></div>
  </section>`);
 $('#req').onsubmit=async e=>{e.preventDefault();const button=$('button[type="submit"]',e.currentTarget);button.disabled=true;$('#reqMsg').textContent='Submitting request…';try{const d=await api('/api/requests',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});$('#reqMsg').textContent=(d.message||'Request submitted.')+(d.cost===undefined?'':' Cost: '+Number(d.cost).toLocaleString()+' Imperial Crowns.');e.currentTarget.reset();const fresh=await api('/api/requests');const quota=$('.in-requests-quota');if(quota)quota.querySelector('b').innerHTML=Number(fresh.used||0)+' <small>/ '+Number(fresh.limit||0)+'</small>'}catch(x){$('#reqMsg').textContent=x.message||'The request could not be submitted.'}finally{button.disabled=false}}
}
async function omni(){
 const root=$('#app');
 root.innerHTML=pageStart('OmniPortal','Rights-first discovery across Imperial Novel and authorized provider connectors.','in-omniportal')+`<div class="in-omni-panel"><form id="omni" class="in-omni-search-form"><div class="in-omni-search-field" style="display:flex"><span>✦</span><input name="q" placeholder="Search titles, authors and worlds..."></div><button class="in-omni-primary">Search</button></form><div class="in-omni-notice"><b>Legal mode:</b> only authorized connectors are queried. Imports are metadata-only by default. Imperial Novel does not bypass paywalls, DRM, logins or access controls, and does not copy source chapters.</div><div id="omniRes" class="in-omni-results" style="margin-top:18px"></div></div></div></div>`;
 $('#omni').onsubmit=async e=>{
  e.preventDefault();
  const q=String(new FormData(e.target).get('q')||'');
  if(q.length<2)return;
  try{
   const d=await api('/api/omni/in-omni-search?q='+encodeURIComponent(q));
   if(!d.results.length){$('#omniRes').innerHTML='<div class="in-omni-empty" style="grid-column:1/-1">No authorized results found.</div>';return;}
   $('#omniRes').innerHTML=d.results.map(x=>{
    const ext=String(x.url||'').startsWith('http');
    return `<div class="in-omni-card"><div class="in-omni-card-body"><span class="in-omni-pill in-omni-purple">${esc(x.provider)}</span><div class="in-omni-card-title" style="margin-top:10px">${esc(x.title)}</div><div class="in-omni-muted">${esc(x.author)}</div><p class="in-omni-muted">${esc(x.description||'')}</p><div class="in-omni-actions" style="margin-top:12px">${ext?`<a class="in-omni-ghost" href="${esc(x.url)}" target="_blank" rel="noopener">Open Source</a><button class="in-omni-secondary omniImport" data-url="${esc(x.url)}">Request Metadata Import</button>`:`<a class="in-omni-primary" href="${esc(x.url)}">Read on Imperial Novel</a>`}</div></div></div>`;
   }).join('');
   document.querySelectorAll('.omniImport').forEach(btn=>{
    btn.onclick=async()=>{
     try{
      const d=await api('/api/omni/import',{method:'POST',body:JSON.stringify({url:btn.dataset.url})});
      alert(`Metadata import request #${d.job_id} queued. No source chapters will be copied.`);
     }catch(err){alert(err.message)}
    };
   });
  }catch(err){alert(err.message)}
 };
}
