async function boot(){const root=document.querySelector('#app')||document.createElement('main');root.id='app';root.className='appBootRoot';root.innerHTML='<section class="in-boot-status" role="status" aria-label="Opening Imperial Novel"><span class="in-boot-mark" aria-hidden="true">IN</span><span class="in-boot-track" aria-hidden="true"></span></section>';if(!document.body.contains(root))document.body.appendChild(root);try{shell();const p=location.pathname;const titles={'/':'Home','/discover':'Discover','/community':'Community','/leaderboard':'Leaderboard','/tier-list':'Tier List','/random':'Random Novel','/made-for-you':'Made For You','/for-you':'Made For You','/trending':'Trending Now','/vote':'Vote Novels','/notifications':'Notifications','/settings':'Settings','/omniportal':'OmniPortal','/author':'Author Studio','/admin':'Command Center','/trend-factory':'Trend Factory'};if(titles[p])document.title=titles[p]+' | Imperial Novel';if(p==='/')await home();else if(p==='/trend-factory')await trendFactory();else if(p==='/discover'||p==='/catalog')await catalog();else if(p==='/formats')await formatDirectory();else if(/^\/format\/[^/]+\/?$/.test(p))await formatLanding(decodeURIComponent(p.split('/')[2]||''));else if(p==='/genres')await genres();else if(p==='/tags')await tags();else if(p==='/search')await search();else if(/^\/novel\/\d+\/chapters\/?$/.test(p))await chapters();else if(/^\/novel\/\d+\/?$/.test(p))await novel();else if(/^\/read\/\d+\/\d+\/?$/.test(p))await reader();else if(p==='/library')await library();else if(p==='/history')await history();else if(p==='/following')await following();else if(p==='/tickets')await tickets();else if(p==='/requests')await requests();else if(p==='/omniportal')await omni();else if(p==='/community')await discoveryPage('community');else if(p==='/leaderboard')await discoveryPage('leaderboard');else if(p==='/tier-list')await discoveryPage('tier-list');else if(p==='/random')await discoveryPage('random');else if(p==='/made-for-you'||p==='/for-you')await discoveryPage('made-for-you');else if(p==='/trending')await discoveryPage('trending');else if(p==='/vote')await discoveryPage('vote');else if(p==='/notifications')await discoveryPage('notifications');else if(p==='/settings')settings();else if(p==='/author')await authorStudio();else if(p==='/account')await account();else if(p==='/login')await authPage('login');else if(p==='/register')await authPage('register');else if(p.startsWith('/fandom/')){const slug=p.split('/').pop();location.href='/catalog?tag='+encodeURIComponent(slug)}else if(/^\/author\/[^/]+$/.test(p))await authorPublic();else simplePage('Page not found','The page you requested does not exist.');}catch(e){console.error('Imperial Novel boot failed',e);root.innerHTML=`<section class="in-system-state" role="alert"><span class="in-boot-mark" aria-hidden="true">IN</span><span class="in-novel-overline">IMPERIAL NOVEL</span><h1>This page could not open.</h1><p>${esc(e&&e.message||'The page could not finish loading.')}</p><button id="inBootRetry" class="in-button in-button--primary" type="button">Try again</button></section>`;$('#inBootRetry').onclick=()=>location.reload()}}
boot();
